use clap::{error::ErrorKind, Parser};

#[derive(Parser)]
struct Cli {
    #[arg(short, long)]
    verbose: bool,
}

fn main() {
    match Cli::try_parse() {
        Ok(cli) => println!("Success: verbose={}", cli.verbose),
        Err(e) => {
            match e.kind() {
                ErrorKind::DisplayVersion => {
                    // Version request - print cleanly and exit 0
                    e.print().expect("print failed");
                    std::process::exit(0);
                }
                ErrorKind::DisplayHelp => {
                    // Help request - print cleanly and exit 0
                    e.print().expect("print failed");
                    std::process::exit(0);
                }
                _ => {
                    // Other errors - print normally and exit 1
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        }
    }
}
